<?php declare(strict_types=1); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#142337"><title>HEX CHEATS SHOP | Customers &amp; orders</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;color:#182638;background:#f3f6f9;--navy:#142337;--blue:#246bce;--line:#e0e7ee;--muted:#708095;--green:#16845f;--red:#bd3b4b}*{box-sizing:border-box}body{margin:0}.top{min-height:66px;background:var(--navy);color:white;display:flex;align-items:center;justify-content:space-between;padding:12px max(16px,calc((100% - 1180px)/2));gap:12px}.brand{font-weight:850;letter-spacing:.03em;color:white;text-decoration:none}.actions{display:flex;gap:8px;flex-wrap:wrap}.wrap{width:min(1180px,calc(100% - 30px));margin:26px auto 55px}.tabs{display:flex;gap:8px;margin:0 0 18px}.button{border:1px solid transparent;border-radius:9px;padding:9px 13px;background:var(--blue);color:white;font-size:12px;font-weight:750;cursor:pointer;text-decoration:none}.button.secondary{background:white;border-color:var(--line);color:#384a5d}.button.danger{background:var(--red)}.button:disabled{opacity:.55;cursor:wait}.tabs .active{background:var(--navy);color:white}.panel{display:none}.panel.active{display:block}.heading{display:flex;justify-content:space-between;align-items:end;gap:12px;margin-bottom:15px}.heading h1{margin:3px 0;font-size:25px;letter-spacing:-.04em}.muted{color:var(--muted);font-size:12px;line-height:1.5}.search{border:1px solid var(--line);border-radius:8px;padding:10px;width:min(290px,100%)}.table-wrap{overflow:auto;background:#fff;border:1px solid var(--line);border-radius:12px}.table{width:100%;border-collapse:collapse;min-width:980px}.table th,.table td{padding:12px;text-align:left;border-bottom:1px solid #edf1f5;font-size:12px;vertical-align:top}.table th{background:#f9fbfc;color:#607186;font-size:10px;text-transform:uppercase;letter-spacing:.08em}.pill{display:inline-block;padding:4px 7px;border-radius:99px;background:#eef3f8;font-size:9px;color:#52647a}.pill.ok{background:#e6f5ef;color:var(--green)}.pill.bad{background:#fff0f0;color:var(--red)}.small{font-size:10px;color:var(--muted);margin-top:4px;word-break:break-word}.key{font-family:ui-monospace,monospace;word-break:break-all;max-width:300px}.key textarea{display:block;width:250px;max-width:100%;min-height:65px;margin:8px 0;border:1px solid var(--line);border-radius:7px;padding:8px;font:11px ui-monospace,monospace}.key summary{font-size:10px;color:var(--blue);cursor:pointer;margin:6px 0}.empty{padding:30px;text-align:center;color:var(--muted)}.status{min-height:20px;color:var(--green);font-size:12px;margin:10px 0}.status.error{color:var(--red)}.warning{background:#fff7df;border:1px solid #f1e3bc;color:#765719;border-radius:8px;padding:10px;font-size:10px;line-height:1.5;margin:0 0 12px}
@media(max-width:650px){.top{align-items:flex-start;flex-direction:column}.wrap{margin-top:18px}.heading{align-items:flex-start;flex-direction:column}.search{width:100%}}
</style></head><body>
<header class="top"><a class="brand" href="/admin/catalog">HEX CHEATS SHOP · ADMIN</a><nav class="actions"><a class="button secondary" href="/admin/homepage">Homepage</a><a class="button secondary" href="/admin/catalog">Catalog</a><button class="button secondary" id="logout">Sign out</button></nav></header>
<main class="wrap"><div class="tabs"><button class="button secondary active" data-panel="customers">Customers</button><button class="button secondary" data-panel="orders">Orders</button><button class="button secondary" data-panel="binance">Binance payments</button></div>
<section class="panel active" id="customers"><div class="heading"><div><div class="muted">Website accounts only</div><h1>Customers</h1></div><input class="search" id="search" type="search" placeholder="Search name or email"></div><div class="table-wrap" id="customerTable"><div class="empty">Loading customers…</div></div></section>
<section class="panel" id="orders"><div class="heading"><div><div class="muted">Recent checkouts and supplier deliveries</div><h1>Orders</h1><div class="muted">If a supplier request times out, check the supplier account/order history before retrying. Support for supplier idempotency headers is not verified.</div></div><button class="button secondary" id="refreshOrders">Refresh</button></div><div class="warning">A confirmed payment is never charged again by a delivery retry. However, the supplier may have issued a key even if the website did not receive its response. Review that supplier transaction before retrying; if a key already exists, save it to the order below instead.</div><div class="table-wrap" id="orderTable"><div class="empty">Loading orders…</div></div></section>
<section class="panel" id="binance"><div class="heading"><div><div class="muted">Manual Binance Pay proof review</div><h1>Binance USD top-ups</h1><div class="muted">Check the actual Binance receipt and transaction ID before approving; approval credits the stored INR quote exactly once.</div></div><button class="button secondary" id="refreshBinance">Refresh</button></div><div class="warning">A screenshot is not proof that funds arrived. Only approve after independently verifying the transaction in your Binance receiving account. Approvals are atomic and cannot be credited twice.</div><div class="table-wrap" id="binanceTable"><div class="empty">Loading Binance requests…</div></div></section><div class="status" id="status"></div></main>
<script>
const $=id=>document.getElementById(id);let token=localStorage.getItem('hex_admin_token')||'',searchTimer=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const headers={...(options.headers||{}),'X-Admin-Token':token};const r=await fetch(path,{...options,headers,credentials:'same-origin'});let data={};try{data=await r.json()}catch{}if(r.status===401){localStorage.removeItem('hex_admin_token');location.href='/admin';throw Error('Admin sign-in required.')}if(!r.ok)throw Error(data.error||'Request failed.');return data}
function date(v){return v?new Date(Number(v)*1000).toLocaleString():'—'}
async function loadCustomers(){const q=$('search').value.trim();try{const d=await api('/admin/api/store/accounts'+(q?'?q='+encodeURIComponent(q):''));const a=d.accounts||[];$('customerTable').innerHTML=a.length?`<table class="table"><thead><tr><th>Customer</th><th>Wallet (INR)</th><th>Created</th><th>Last login</th><th>Status</th><th>Action</th></tr></thead><tbody>${a.map(x=>`<tr><td><b>${esc(x.display_name||'Customer')}</b><div class="small">${esc(x.email||'')}</div></td><td>₹${Number(x.balance_inr||0).toFixed(2)}</td><td>${esc(date(x.created_at))}</td><td>${esc(date(x.last_login_at))}</td><td><span class="pill ${x.disabled?'bad':'ok'}">${x.disabled?'Disabled':'Active'}</span></td><td><button class="button secondary" data-wallet="${Number(x.id)}">Adjust wallet</button> <button class="button ${x.disabled?'secondary':'danger'}" data-account="${Number(x.id)}" data-disabled="${x.disabled?0:1}">${x.disabled?'Enable':'Disable'}</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No customers found.</div>'}catch(e){$('customerTable').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function loadOrders(){try{const d=await api('/admin/api/store/orders');const a=d.orders||[];$('orderTable').innerHTML=a.length?`<table class="table"><thead><tr><th>Order</th><th>Customer</th><th>Product</th><th>Payment / supplier</th><th>Delivery key / recovery</th><th>Time</th></tr></thead><tbody>${a.map(x=>{const stale=x.status==='delivering'&&Date.now()/1000-Number(x.updated_at||0)>180;const canReview=['paid_delivery_failed','delivery_unknown'].includes(x.status)||stale;return `<tr><td><b>${esc(x.order_id)}</b><div class="small">Payment ref: ${esc(x.transaction_id||'—')}</div><div class="small">Supplier tries: ${Number(x.fulfillment_attempt_count||0)} · ${esc(x.last_fulfillment_attempt_status||'none')}</div></td><td>${esc(x.email||'')}</td><td>${esc(x.product_name)}<div class="small">${esc(x.duration)} · ₹${esc(x.amount)}</div></td><td><span class="pill ${x.status==='complete'?'ok':(['failed','paid_delivery_failed','delivery_unknown','amount_review'].includes(x.status)?'bad':'')}">${esc(x.status)}</span>${x.last_provider_status?`<div class="small">Supplier status: ${esc(x.last_provider_status)}</div>`:''}${x.last_fulfillment_error?`<div class="small">${esc(x.last_fulfillment_error)}</div>`:''}${canReview?`<div style="margin-top:7px"><button class="button" data-retry="${esc(x.order_id)}">${stale?'Review stuck request':'Retry after supplier check'}</button></div>`:''}</td><td class="key">${x.delivery_key?esc(x.delivery_key):'—'}${canReview?`<details><summary>Save key already issued by supplier</summary><textarea maxlength="4096" data-manual-value placeholder="Paste the supplier-issued key"></textarea><button class="button secondary" data-manual="${esc(x.order_id)}">Save recovered key</button></details>`:''}</td><td>${esc(date(x.created_at))}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No orders yet.</div>'}catch(e){$('orderTable').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function loadBinance(){try{const d=await api('/admin/api/store/wallet/binance');const a=d.payments||[];$('binanceTable').innerHTML=a.length?`<table class="table"><thead><tr><th>Request / customer</th><th>Payment amount</th><th>Proof</th><th>Status</th><th>Review</th></tr></thead><tbody>${a.map(x=>{const pending=x.status==='proof_submitted'&&x.proof_filename;return `<tr><td><b>${esc(x.order_id)}</b><div class="small">${esc(x.display_name||'Customer')} · ${esc(x.email||'')}</div><div class="small">Created ${esc(date(x.created_at))}${x.reviewed_at?` · reviewed ${esc(date(x.reviewed_at))}`:''}</div></td><td><b>$${Number(x.amount_usd||0).toFixed(2)} USD</b><div class="small">Wallet credit: ₹${Number(x.amount_inr||0).toFixed(2)}</div><div class="small">Quoted at ₹${Number(x.exchange_rate_inr||0).toFixed(4)}/USD</div></td><td>${x.proof_filename?`<button class="button secondary" data-proof="${esc(x.order_id)}">View screenshot</button><div class="small">TXID: ${esc(x.proof_txid||'—')}</div>`:'<span class="muted">Not submitted</span>'}</td><td><span class="pill ${x.status==='approved'?'ok':(['rejected','failed'].includes(x.status)?'bad':'')}">${esc(x.status)}</span>${x.review_note?`<div class="small">${esc(x.review_note)}</div>`:''}</td><td>${pending?`<button class="button" data-payment-review="approved" data-order="${esc(x.order_id)}" data-usd="${Number(x.amount_usd||0)}" data-inr="${Number(x.amount_inr||0)}">Verify &amp; credit</button> <button class="button danger" data-payment-review="rejected" data-order="${esc(x.order_id)}">Reject</button>`:'—'}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No Binance top-ups have been created.</div>'}catch(e){$('binanceTable').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
$('search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(loadCustomers,250)});$('refreshOrders').addEventListener('click',loadOrders);$('refreshBinance').addEventListener('click',loadBinance);$('logout').addEventListener('click',()=>{localStorage.removeItem('hex_admin_token');location.href='/admin'});
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-panel]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id===b.dataset.panel));if(b.dataset.panel==='orders')loadOrders();if(b.dataset.panel==='binance')loadBinance()}));
document.addEventListener('click',async e=>{const accountButton=e.target.closest('[data-account]'),walletButton=e.target.closest('[data-wallet]'),retry=e.target.closest('[data-retry]'),manual=e.target.closest('[data-manual]'),proof=e.target.closest('[data-proof]'),paymentReview=e.target.closest('[data-payment-review]');try{if(proof){const tab=window.open('about:blank','_blank');const response=await fetch(`/admin/api/store/wallet/binance/${encodeURIComponent(proof.dataset.proof)}/proof`,{headers:{'X-Admin-Token':token},credentials:'same-origin'});if(!response.ok){if(tab)tab.close();let payload={};try{payload=await response.json()}catch{}throw Error(payload.error||'Could not open the payment proof.')}const url=URL.createObjectURL(await response.blob());if(tab)tab.location.href=url;else window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}if(paymentReview){const status=paymentReview.dataset.paymentReview,order=paymentReview.dataset.order;if(status==='approved'&&!confirm(`Confirm you independently checked Binance and received the exact payment for ${order} ($${Number(paymentReview.dataset.usd).toFixed(2)}), and want to credit ₹${Number(paymentReview.dataset.inr).toFixed(2)} once?`))return;if(status==='rejected'&&!confirm(`Reject the Binance payment proof for ${order}? No wallet funds will be credited.`))return;paymentReview.disabled=true;await api(`/admin/api/store/wallet/binance/${encodeURIComponent(order)}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status,confirm_payment_checked:true})});await Promise.all([loadBinance(),loadCustomers()]);$('status').textContent=status==='approved'?'Binance payment verified and wallet credited once.':'Binance payment proof rejected.'}if(accountButton){accountButton.disabled=true;await api(`/admin/api/store/accounts/${accountButton.dataset.account}/status`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({disabled:accountButton.dataset.disabled==='1'})});await loadCustomers()}if(walletButton){const amount=prompt('Enter wallet adjustment in INR. Positive adds funds; negative deducts funds.','0');if(amount===null)return;const value=Number(amount);if(!Number.isFinite(value)||value===0)throw Error('Enter a valid non-zero amount.');const reason=prompt('Required reason for the ledger:','');if(reason===null)return;if(!reason.trim())throw Error('A reason is required.');if(!confirm(`Apply ${value>0?'credit':'debit'} of ₹${Math.abs(value).toFixed(2)}? This is recorded in the wallet ledger.`))return;walletButton.disabled=true;await api(`/admin/api/store/accounts/${walletButton.dataset.wallet}/wallet`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount_inr:value,reason:reason.trim()})});await loadCustomers();$('status').textContent='Wallet adjustment saved to the ledger.'}if(retry){if(!confirm('Check the supplier account/order history for this exact order first. It may already have issued a key. Continue with a retry only after checking?'))return;retry.disabled=true;await api(`/admin/api/store/orders/${encodeURIComponent(retry.dataset.retry)}/retry`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm_provider_checked:true})});await loadOrders();$('status').textContent='Supplier retry recorded.'}if(manual){const key=manual.closest('details')?.querySelector('[data-manual-value]')?.value.trim();if(!key){$('status').textContent='Paste the recovered supplier key first.';$('status').className='status error';return}if(!confirm('Confirm this key was issued by the supplier for this order and that you checked the supplier account?'))return;manual.disabled=true;await api(`/admin/api/store/orders/${encodeURIComponent(manual.dataset.manual)}/manual-key`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({delivery_key:key,confirm_provider_checked:true})});await loadOrders();$('status').textContent='Recovered key saved to the existing order.'}}catch(err){$('status').textContent=err.message;$('status').className='status error'}finally{if(accountButton)accountButton.disabled=false;if(walletButton)walletButton.disabled=false;if(retry)retry.disabled=false;if(manual)manual.disabled=false;if(paymentReview)paymentReview.disabled=false}});
if(!token)location.href='/admin';else{loadCustomers();loadOrders();loadBinance()}
</script></body></html>
